// tb_policy_update - bounded-authority validation, dual-bank activation, rollback and reset tests.
//   +vdir=build/vectors   policy images and attacks.txt generated by scripts/run_rtl.py
//   +measure +policy=P.hex  only measure validation/update latency (any NRULES)
`timescale 1ns/1ps
module tb_policy_update;
  parameter int NRULES = 8;
  localparam int MODE = 2;
`include "tb_common.svh"

  security_monitor_top #(.NRULES(NRULES), .MODE(MODE)) dut (.*);

  string vdir = "build/vectors";

  task automatic load(input string name);
    read_policy($sformatf("%s/%s.hex", vdir, name));
  endtask

  task automatic expect_status(input [3:0] state, input string tag);
    logic [31:0] s;
    rd(A_STATUS, s);
    check(st(s) == state, $sformatf("%s: state %0d, expected %0d", tag, st(s), state));
  endtask

  task automatic expect_version(input [31:0] v, input string tag);
    logic [31:0] s;
    rd(A_ACTIVE_VERSION, s);
    check(s == v, $sformatf("%s: active version %0d, expected %0d", tag, s, v));
  endtask

  // Probe transactions whose outcome distinguishes v1..v4 (scenario 1/2/3 + authority boundaries)
  task automatic probes(input int ver, input string tag);
    expect_txn(1, 32'h1000_8000, 1, 0, 1, ver == 1 ? 1 : 0, ver == 1 ? V_OK : V_NO_RULE, {tag, " s1 DMA->protected"});
    expect_txn(1, 32'h1000_9000, 1, 0, 1, ver > 0 ? 1 : 0, ver > 0 ? V_OK : V_NO_RULE, {tag, " DMA legit"});
    expect_txn(0, 32'h0000_F000, 0, 0, 1, (ver == 1 || ver == 2) ? 1 : 0,
               ver == 0 ? V_NO_RULE : (ver < 3 ? V_OK : V_PRIV), {tag, " s2 unpriv peripheral"});
    expect_txn(0, 32'h0000_F000, 0, 1, 1, ver > 0 ? 1 : 0, ver > 0 ? V_OK : V_NO_RULE, {tag, " priv peripheral"});
    expect_txn(1, 32'h1000_0000, 0, 0, 32, (ver > 0 && ver < 4) ? 1 : 0,
               ver == 0 ? V_NO_RULE : (ver < 4 ? V_OK : V_BURST), {tag, " s3 DMA burst 32"});
    expect_txn(2, 32'h2000_0000, 1, 1, 1, 0, ver == 0 ? V_NO_RULE : V_WRITE_DENIED, {tag, " DIAG write"});
  endtask

  // Bring the device to v4 from reset (boot restore v1, then the owner-signed chain).
  task automatic chain_to_v4();
    do_reset();
    load("policy_v1"); install_pw(E_NONE, 0, "restore v1");
    load("policy_v2"); install_pw(E_NONE, 0, "v2 by DMA");
    load("policy_v3"); install_pw(E_NONE, 0, "v3 by CPU");
    load("policy_v4"); install_pw(E_NONE, 0, "v4 by DMA");
  endtask

  // Stage + validate pw, leaving the controller in READY (or wherever validation ended).
  task automatic stage_validate(output [31:0] s);
    stage_pw(); wr(A_CMD, {28'd0, C_VALIDATE}); wait_not_busy(s);
  endtask

  // ------------------------------------------------------------------------------------------
  task automatic t_boot_and_chain();
    logic [31:0] s;
    rd(A_STATUS, s);
    check(st(s) == S_IDLE && s[6] && !s[5], "reset: IDLE, boot window open, bank 0 active");
    rd(A_HW_INFO, s); check(s == 32'h4802_0308, "HW_INFO");
    expect_version(0, "reset");
    probes(0, "reset");

    load("policy_v1"); install_pw(E_NONE, 0, "boot restore v1");
    rd(A_STATUS, s); check(!s[6] && s[5], "after restore: window closed, bank 1 active");
    expect_version(1, "v1"); probes(1, "v1");

    load("policy_v1"); pw[1] = 9; install_pw(E_AUTH, 0, "ROOT after boot window closed");
    load("policy_v2"); pw[0] = 3; install_pw(E_AUTH, 0, "unknown requester");
    load("policy_v2"); pw[2] = 0; install_pw(E_COUNT, 0, "rule count 0");
    load("policy_v2"); pw[2] = 9; install_pw(E_COUNT, 0, "rule count 9");
    load("policy_v2"); pw[2] = 5; for (int k = 0; k < 4; k++) pw[19+k] = pw[15+k];   // 5th write repeats rule 4
    install_pw(E_COUNT, 0, "declared count != rules written");
    load("policy_v2"); pw[1] = 1; install_pw(E_VERSION, 0, "same version (replay)");
    load("policy_v2"); pw[1] = 0; install_pw(E_VERSION, 0, "older version");
    expect_version(1, "after rejected attempts"); probes(1, "v1 unchanged");

    load("policy_v2"); install_pw(E_NONE, 0, "v2 by DMA");
    expect_version(2, "v2"); probes(2, "v2");
    rd(A_PREV_VERSION, s); check(s == 1, "prev version 1");
    load("policy_v3"); install_pw(E_NONE, 0, "v3 by CPU"); probes(3, "v3");
    load("policy_v4"); install_pw(E_NONE, 0, "v4 by DMA"); probes(4, "v4");
    expect_version(4, "v4");
  endtask

  // Attack images signed by real owners; expectations from the Python reference model.
  task automatic t_attacks();
    int fd, r, n = 0;
    logic [8*64-1:0] name;
    logic [31:0] err, slot, s0, s1;
    fd = $fopen($sformatf("%s/attacks.txt", vdir), "r");
    check(fd != 0, "attacks.txt present");
    rd(A_STATUS, s0);
    while (fd != 0 && $fscanf(fd, "%s %d %d\n", name, err, slot) == 3) begin
      load($sformatf("%0s", name));
      install_pw(err[7:0], slot[2:0], $sformatf("%0s", name));
      expect_version(4, $sformatf("%0s leaves v4 active", name));
      rd(A_STATUS, s1); check(s1[5] == s0[5], $sformatf("%0s leaves the bank select unchanged", name));
      n++;
    end
    if (fd) $fclose(fd);
    check(n == 8, $sformatf("%0d attack images replayed", n));
    probes(4, "v4 after all attacks");
  endtask

  task automatic t_structure();
    logic [31:0] s;
    // Encoding errors seen by the controller during RECEIVE
    load("policy_v4"); pw[1] = 5; stage_pw();
    wr(rule_reg(5, 2), 32'h8001_1010);                     // reserved bit 12 set
    wr(A_CMD, {28'd0, C_VALIDATE}); wait_not_busy(s);
    check(st(s) == S_ERROR && s[15:8] == E_MALFORMED, "reserved ATTR bit -> MALFORMED"); wr(A_CMD, {28'd0, C_ABORT});
    load("policy_v4"); pw[1] = 5; stage_pw(); wr(8'h4C, 32'd0);  // field 3 of slot 0
    wr(A_CMD, {28'd0, C_VALIDATE}); wait_not_busy(s);
    check(st(s) == S_ERROR && s[15:8] == E_MALFORMED, "write to reserved rule field -> MALFORMED"); wr(A_CMD, {28'd0, C_ABORT});
    load("policy_v4"); pw[1] = 5; stage_pw(); wr(8'h41, 32'd0);  // unaligned
    wr(A_CMD, {28'd0, C_VALIDATE}); wait_not_busy(s);
    check(st(s) == S_ERROR && s[15:8] == E_MALFORMED, "unaligned rule write -> MALFORMED"); wr(A_CMD, {28'd0, C_ABORT});
    // Semantic errors (DMA-owned slot 1 of v4)
    load("policy_v4"); pw[1] = 5; pw[9] = 32'h0FFF_FFFF; install_pw(E_RANGE, 1, "start > end");
    load("policy_v4"); pw[1] = 5; pw[10] = 32'h8001_0300; install_pw(E_MALFORMED, 1, "max burst 0");
    load("policy_v4"); pw[1] = 5; pw[10] = 32'h8005_0310; install_pw(E_FOREIGN, 1, "rule owner 5 from DMA");
    // Tightening its own rule is within authority: drop W, add a privilege requirement.
    load("policy_v4"); pw[1] = 5; pw[10] = 32'h8001_0110; stage_validate(s);
    check(st(s) == S_READY, "owner may remove its own write permission"); wr(A_CMD, {28'd0, C_ABORT});
    load("policy_v4"); pw[1] = 5; pw[10] = 32'h8001_0710; stage_validate(s);
    check(st(s) == S_READY, "owner may add a privilege requirement"); wr(A_CMD, {28'd0, C_ABORT});
    load("policy_v4"); pw[1] = 5; pw[10] = 32'h8000_0310; install_pw(E_FOREIGN, 1, "DMA hands its rule to the CPU");
    // TOCTOU: changing REQ_OWNER after BEGIN must not change the authenticated requester
    load("attacks/atk_dma_foreign_modify"); stage_pw();
    wr(A_REQ_OWNER, OWNER_CPU);
    rd(A_REQ_OWNER, s); check(s == OWNER_DMA, "REQ_OWNER frozen after BEGIN");
    wr(A_CMD, {28'd0, C_VALIDATE}); wait_not_busy(s);
    check(st(s) == S_ERROR && s[15:8] == E_FOREIGN, "requester stays DMA -> FOREIGN"); wr(A_CMD, {28'd0, C_ABORT});
    expect_version(4, "after structure tests"); probes(4, "v4 after structure tests");
  endtask

  // Root-mode checks need an empty active bank: run right after a reset.
  task automatic t_root_checks();
    load("policy_v1"); pw[10] = 32'h8005_0340; install_pw(E_OWNER_ID, 1, "boot image with owner 5");
    // policy_v1 rules sit exactly on the envelope bounds and are accepted elsewhere; one address
    // outside either bound must be refused, for every owner.
    load("policy_v1"); pw[9]  = 32'h1001_0000; install_pw(E_ADDR_ESCAPE, 1, "DMA end one past envelope");
    load("policy_v1"); pw[8]  = 32'h0FFF_FFFF; install_pw(E_ADDR_ESCAPE, 1, "DMA start one below envelope");
    load("policy_v1"); pw[5]  = 32'h0001_0000; install_pw(E_ADDR_ESCAPE, 0, "CPU end one past envelope");
    load("policy_v1"); pw[12] = 32'h1FFF_FFFF; install_pw(E_ADDR_ESCAPE, 2, "DIAG start one below envelope");
    load("policy_v1"); pw[13] = 32'h2001_0000; install_pw(E_ADDR_ESCAPE, 2, "DIAG end one past envelope");
    load("policy_v1"); pw[14] = 32'h8002_0704; install_pw(E_PERM_ESC, 2, "boot image DIAG write");
    load("policy_v1"); pw[14] = 32'h8002_0104; install_pw(E_PRIV_FLOOR, 2, "boot image DIAG unprivileged");
    load("policy_v1"); pw[2] = 4; pw[15] = 3; pw[16] = 32'h1000_F000; pw[17] = 32'h1000_FFFF; pw[18] = 32'h8001_0310;
    install_pw(E_OVERLAP, 3, "boot image overlap");
    // Overlap in the very last pair (slots 6 and 7) must be found too.
    load("policy_v1"); pw[9] = 32'h1000_0FFF; pw[2] = 5;
    pw[15] = 6; pw[16] = 32'h1000_8000; pw[17] = 32'h1000_8FFF; pw[18] = 32'h8001_0310;
    pw[19] = 7; pw[20] = 32'h1000_8800; pw[21] = 32'h1000_9FFF; pw[22] = 32'h8001_0310;
    install_pw(E_OVERLAP, 7, "overlap between slots 6 and 7");
    expect_version(0, "boot checks leave the device empty"); probes(0, "still default-deny");
    // A full 8-slot policy is accepted and slot 7 is enforced.
    load("scaled_8"); install_pw(E_NONE, 0, "8-rule policy");
    expect_txn(1, 32'h1000_2000, 1, 0, 64, 1, V_OK, "slot 7 rule of the 8-rule policy");
    check(dec_rule == 7, "decision reports slot 7");
  endtask

  task automatic t_write_protection_and_revert();
    logic [31:0] s;
    // Rule writes outside RECEIVE are ignored: the active bank has no write path at all.
    wr(rule_reg(1, 0), 32'h1000_8000); wr(rule_reg(1, 1), 32'h1000_8FFF); wr(rule_reg(1, 2), 32'h8001_0310);
    wr(A_CMD, {28'd0, C_ACTIVATE}); wr(A_CMD, {28'd0, C_CONFIRM}); wr(A_CMD, {28'd0, C_REVERT}); wr(A_CMD, {28'd0, C_VALIDATE});
    expect_status(S_IDLE, "illegal commands ignored in IDLE"); probes(4, "v4 after stray writes");
    // Validated candidate cannot be modified in READY (no time-of-check/time-of-use gap)
    load("candidates/cand_v5_dma_reopen"); stage_validate(s);
    check(st(s) == S_READY, "in-authority v5 validates");
    wr(rule_reg(1, 2), 32'h8001_0340);                        // try to raise burst after validation
    wr(A_CMD, {28'd0, C_ACTIVATE}); wait_not_busy(s); check(st(s) == S_COMPLETE && s[7], "COMPLETE, revert available");
    expect_version(5, "v5 trial");
    expect_txn(1, 32'h1000_8000, 1, 0, 16, 1, V_OK, "v5 active (re-opened window)");
    expect_txn(1, 32'h1000_0000, 1, 0, 17, 0, V_BURST, "post-validation write was ignored");
    // Revert to the retained previous bank
    wr(A_CMD, {28'd0, C_REVERT}); wait_not_busy(s);
    check(st(s) == S_IDLE, "revert returns to IDLE");
    expect_version(4, "after revert"); probes(4, "v4 restored by revert");
    // Abort from RECEIVE / READY / WAIT_IDLE leaves the active policy alone
    load("candidates/cand_v5_dma_reopen"); stage_pw(); wr(A_CMD, {28'd0, C_ABORT}); wait_not_busy(s);
    check(st(s) == S_IDLE, "abort in RECEIVE");
    load("candidates/cand_v5_dma_reopen"); stage_validate(s); wr(A_CMD, {28'd0, C_ABORT}); wait_not_busy(s);
    check(st(s) == S_IDLE, "abort in READY");
    load("candidates/cand_v5_dma_reopen"); stage_validate(s); bus_idle = 0; wr(A_CMD, {28'd0, C_ACTIVATE});
    tick(5); wr(A_CMD, {28'd0, C_ABORT}); bus_idle = 1; wait_not_busy(s);
    check(st(s) == S_IDLE, "abort in WAIT_IDLE");
    expect_version(4, "after aborts"); probes(4, "v4 after aborts");
  endtask

  task automatic t_safe_switch();
    logic [31:0] s, s0;
    int accepted_during_hold = 0, flips = 0, decisions = 0;
    logic prev_allow, first = 1;
    // (a) Bus busy: the switch waits, new transactions are held, nothing changes.
    load("candidates/cand_v5_dma_reopen"); stage_validate(s);
    rd(A_STATUS, s0);
    bus_idle = 0; wr(A_CMD, {28'd0, C_ACTIVATE});
    txn_master = 1; txn_addr = 32'h1000_8000; txn_write = 1; txn_priv = 0; txn_burst = 1; txn_valid = 1;
    for (int c = 0; c < 20; c++) begin
      rd(A_STATUS, s);
      check(st(s) == S_WAIT_IDLE && !txn_ready && s[5] == s0[5], "held in WAIT_IDLE while bus busy");
      tick(); if (dec_valid) accepted_during_hold++;
    end
    check(accepted_during_hold == 0, "no transaction accepted while the switch is pending");
    bus_idle = 1;
    while (!dec_valid) tick();                                 // the held transaction goes through...
    check(dec_allow, "...and is decided by the NEW policy");
    txn_valid = 0;
    rd(A_STATUS, s); check(st(s) == S_COMPLETE && s[5] != s0[5], "bank switched once bus idle");
    wr(A_CMD, {28'd0, C_REVERT}); wait_not_busy(s);
    // (b) Continuous traffic: a distinguishing probe every cycle; decisions must change exactly once.
    load("candidates/cand_v5_dma_reopen"); stage_validate(s);
    txn_master = 1; txn_addr = 32'h1000_8000; txn_write = 1; txn_priv = 0; txn_burst = 1; txn_valid = 1;
    fork
      begin tick(3); wr(A_CMD, {28'd0, C_ACTIVATE}); end
      for (int c = 0; c < 40; c++) begin
        tick();
        if (dec_valid) begin
          decisions++;
          if (!first && dec_allow != prev_allow) flips++;
          prev_allow = dec_allow; first = 0;
        end
      end
    join
    txn_valid = 0;
    check(flips == 1 && prev_allow == 1, $sformatf("single clean cut-over (%0d flips in %0d decisions)", flips, decisions));
    wr(A_CMD, {28'd0, C_REVERT}); wait_not_busy(s);
    expect_version(4, "after safe-switch tests");
  endtask

  // Interconnect that registers its outstanding-beat counter, i.e. learns about a grant one
  // cycle after dec_valid. A burst granted in the same cycle as ACTIVATE must still finish
  // its data phase before the bank select flips.
  bit          reg_ic = 0;
  int          ic_beats = 0;
  logic [7:0]  acc_burst;
  always @(posedge clk) if (txn_valid && txn_ready) acc_burst <= txn_burst;
  always @(posedge clk) if (reg_ic) ic_beats <= (dec_valid && dec_allow) ? acc_burst : (ic_beats > 0 ? ic_beats - 1 : 0);
  always @(ic_beats or reg_ic) if (reg_ic) bus_idle = (ic_beats == 0);

  task automatic t_registered_interconnect();
    logic [31:0] s;
    int switch_cycles = 0, busy_at_switch = 0;
    load("candidates/cand_v5_dma_reopen"); stage_validate(s);
    reg_ic = 1;
    txn_master = 1; txn_addr = 32'h1000_0000; txn_write = 1; txn_priv = 0; txn_burst = 8; txn_valid = 1;
    wr(A_CMD, {28'd0, C_ACTIVATE});                 // the burst is granted on this same edge
    txn_valid = 0;
    check(dec_valid && dec_allow, "burst granted in the ACTIVATE cycle");
    for (int c = 0; c < 30; c++) begin
      rd(A_STATUS, s);
      if (st(s) == S_SWITCH) begin switch_cycles++; if (ic_beats != 0) busy_at_switch++; end
      tick();
    end
    check(switch_cycles == 1, $sformatf("exactly one SWITCH cycle (%0d)", switch_cycles));
    check(busy_at_switch == 0, "bank select never flips while a granted burst is in its data phase");
    rd(A_STATUS, s); check(st(s) == S_COMPLETE, "switch completes after the burst drains");
    reg_ic = 0; bus_idle = 1;
    wr(A_CMD, {28'd0, C_REVERT}); wait_not_busy(s);
    expect_version(4, "after registered-interconnect test");
  endtask

  task automatic t_reset_during_update();
    logic [31:0] s;
    int stop_state [6];
    stop_state[0] = S_RECEIVE; stop_state[1] = S_VALIDATE; stop_state[2] = S_READY;  // no array literal: Icarus 12
    stop_state[3] = S_WAIT_IDLE; stop_state[4] = S_SWITCH; stop_state[5] = S_COMPLETE;
    for (int k = 0; k < 6; k++) begin
      chain_to_v4();
      load("candidates/cand_v5_dma_reopen");
      stage_pw();
      if (stop_state[k] != S_RECEIVE) begin
        wr(A_CMD, {28'd0, C_VALIDATE});
        if (stop_state[k] == S_VALIDATE) tick(3);
        else wait_not_busy(s);
      end
      if (stop_state[k] == S_WAIT_IDLE) begin bus_idle = 0; wr(A_CMD, {28'd0, C_ACTIVATE}); tick(2); end
      if (stop_state[k] == S_SWITCH) begin wr(A_CMD, {28'd0, C_ACTIVATE}); tick(1); end   // reset in the flip cycle
      if (stop_state[k] == S_COMPLETE) begin wr(A_CMD, {28'd0, C_ACTIVATE}); wait_not_busy(s); end
      expect_status(4'(stop_state[k]), $sformatf("reached state %0d", stop_state[k]));
      bus_idle = 1;
      do_reset();
      rd(A_STATUS, s);
      check(st(s) == S_IDLE && s[6], $sformatf("reset in state %0d -> IDLE, boot window open", stop_state[k]));
      expect_version(0, "volatile policy state cleared");
      probes(0, "no partially loaded rule is active");
      // Firmware restores the last COMMITTED policy (v4) through the boot window.
      load("policy_v4"); pw[0] = OWNER_ROOT; install_pw(E_NONE, 0, "restore committed v4");
      probes(4, "committed v4 restored");
    end
  endtask

  // ------------------------------------------------------------------------------------------
  // Validator vectors from tests/independent_model.py (73 words each): optional committed base policy,
  // then requester, version, declared count and raw rule writes; expected error code and slot.
  logic [31:0] vv [0:262143];
  task automatic valvec(input string f);
    int nv, b, mism;
    logic [31:0] s, got_err, got_slot;
    mism = 0;
    $readmemh(f, vv);
    nv = vv[0];
    for (int n = 0; n < nv; n++) begin
      b = 1 + n * 73;
      do_reset();
      if (vv[b] != 0) begin
        pw[0] = {28'd0, OWNER_ROOT}; pw[1] = vv[b+1]; pw[2] = vv[b+2];
        for (int k = 0; k < 32; k++) pw[3+k] = vv[b+3+k];
        install_pw(E_NONE, 0, "independent base policy");
      end
      wr(A_REQ_OWNER, vv[b+35]); wr(A_CAND_VERSION, vv[b+36]); wr(A_RULE_COUNT, vv[b+37]); wr(A_CMD, {28'd0, C_BEGIN});
      rd(A_STATUS, s);
      if (st(s) == S_RECEIVE) begin
        for (int w = 0; w < vv[b+38]; w++) begin
          wr(rule_reg(vv[b+39+4*w], 0), vv[b+40+4*w]);
          wr(rule_reg(vv[b+39+4*w], 1), vv[b+41+4*w]);
          wr(rule_reg(vv[b+39+4*w], 2), vv[b+42+4*w]);
        end
        wr(A_CMD, {28'd0, C_VALIDATE}); wait_not_busy(s);
      end
      got_err  = (st(s) == S_READY) ? 32'd0 : {24'd0, s[15:8]};
      got_slot = (st(s) == S_READY) ? 32'd0 : {29'd0, s[18:16]};
      if (!(st(s) == S_READY || st(s) == S_ERROR) || got_err != vv[b+71] || got_slot != vv[b+72]) begin
        mism++;
        if (mism <= 10) $display("  vector %0d: RTL state %0d err %0d slot %0d, independent model err %0d slot %0d",
                                 n, st(s), got_err, got_slot, vv[b+71], vv[b+72]);
      end
    end
    check(nv > 0, "validator vectors loaded");
    check(mism == 0, $sformatf("%0d of %0d validator outcomes differ from the independent model", mism, nv));
    $display("VALVEC compared=%0d mismatches=%0d", nv, mism);
  endtask

  task automatic measure();
    logic [31:0] s;
    int t_start, t_val, t_ready, t_done, stall = 0;
    t_start = cycle;
    stage_pw();
    wr(A_CMD, {28'd0, C_VALIDATE}); t_val = cycle;
    rd(A_STATUS, s);
    while (st(s) == S_VALIDATE) begin tick(); rd(A_STATUS, s); end
    t_ready = cycle;
    check(st(s) == S_READY, "measured policy validates");
    wr(A_CMD, {28'd0, C_ACTIVATE});
    rd(A_STATUS, s);
    while (s[4]) begin if (!txn_ready) stall++; tick(); rd(A_STATUS, s); end
    t_done = cycle;
    check(st(s) == S_COMPLETE, "measured policy activates");
    $display("METRIC nrules=%0d rules=%0d validate_cycles=%0d update_cycles=%0d mmio_writes=%0d switch_hold_cycles=%0d",
             NRULES, pw[2], t_ready - t_val, t_done - t_start, 4 + 3 * pw[2] + 2, stall);
  endtask

  initial begin
    string pf;
    void'($value$plusargs("vdir=%s", vdir));
    do_reset();
    if ($value$plusargs("valvec=%s", pf)) begin
      valvec(pf);
      finish("tb_policy_update[valvec]");
    end
    if ($test$plusargs("measure")) begin
      void'($value$plusargs("policy=%s", pf));
      read_policy(pf);
      measure();
      finish($sformatf("tb_policy_update[measure,N=%0d]", NRULES));
    end
    t_boot_and_chain();
    t_attacks();
    t_structure();
    t_write_protection_and_revert();
    t_safe_switch();
    t_registered_interconnect();
    t_reset_during_update();
    do_reset();
    t_root_checks();
    finish("tb_policy_update");
  end

endmodule
